class InvalidOperation(Exception):
    """You're not supposed to do that."""


INDENT = 2


class _Key:
    """Key class description"""

    _PARENT = None

    def __init__(self, key):
        self._key = key

    def __init_subclass__(cls, parent=None):
        cls._PARENT = parent

    def __hash__(self):
        return hash(self.key)

    def __eq__(self, other):
        return self.key == other.key

    @property
    def key(self):
        return self._key

    @classmethod
    def parent(cls):
        """access the classes parent attribute"""
        return cls._PARENT

    def __str__(self):
        return f"[{self._key}]"

    def __repr__(self):
        return f"[{self._key}]"


class Key:
    """A key contains one or multiple _Key objects"""

    def __init__(self, *keys):
        self._keys = []
        for _key in keys:
            if isinstance(_key, Key):
                self._keys += _key.as_list()
            elif isinstance(_key, _Key):
                self._keys += [_key]
            else:
                self._keys += [_Key(_key)]

    def unchain(self, tagged=False):
        """unpack all the key objects chained up"""
        for _key in self._keys:
            if tagged:
                yield (_key.parent(), _key)
            else:
                yield _key

    def __hash__(self):
        return hash(self.keys)

    def __eq__(self, other):
        return self.keys == other.keys

    @property
    def keys(self):
        """unpack the key signature as a tuple for hashing and more"""
        return tuple(_key.key for _key in self._keys)

    def as_list(self, tagged=False):
        """access the keys as a list"""
        return list(self.unchain(tagged=tagged))

    def __repr__(self):
        return f"[{'|'.join(map(lambda x: str(x.key), self._keys))}]"

    def __str__(self):
        return f"<K{self.__repr__()}>"

    def __or__(self, other):
        if isinstance(other, Key):
            return Key(self, other.as_list())
        elif isinstance(other, _Key):
            return Key(self, other)
        else:
            return Key(self, _Key(other))

    def __ror__(self, other):
        if isinstance(other, Key):
            return Key(other.as_list(), self)
        elif isinstance(other, _Key):
            return Key(other, self)
        else:
            return Key(_Key(other), self)

    @property
    def parents(self):
        """access the classes parent attribute"""
        return [_key.parent() for _key in self._keys]


def autoname(function):
    """decorator to automatically fill a proper name"""

    def wrapper(self, name=None):
        if name is None:
            name = f"{self._IDENTIFIER_}{self._ENUM_}"
        self.__class__._ENUM_ += 1  # count

        function(self, name=name)

    return wrapper


class KeyMap:
    """Keymap class description"""

    _IDENTIFIER_ = "KeyMap"
    _ENUM_ = 0

    @autoname
    def __init__(self, name=None):
        super().__init__()

        self._name = name

        # start empty
        self._size = 0

        # contain nested keymaps, regions or entries
        self._content = []

        # remember what you are attached to
        self._parents = []

        # lookup tables
        self._pos2reg = []  # translate from pos to key reg
        self._key2pos = {}  # translate the key to its position
        self._key2reg = {}

        # reset
        self._reset()

        # this actually does not make a difference, but it feels more safe to
        # start with False
        self._is_ud_flag = False

        self._keygen = self._generate_keygen(name)

    def _generate_keygen(self, name):
        class ThisKeyGen(_Key, parent=self):
            pass

        ThisKeyGen.__doc__ = (
            f"auto generated key generator for keymap '{name}.'"
        )
        return ThisKeyGen

    def _reset(self):
        """reset anything that has to do with counters and offsets"""
        self._is_ud_flag = False
        self._size = 0
        self._pos2reg = []
        self._key2pos = {}
        self._key2reg = {}

    @property
    def name(self):
        """get name (protected access)"""
        return self._name

    @name.setter
    def name(self, name):
        print("Bad programmer, bad! But seriously, be careful with renaming.")
        self._name = name

    @property
    def size(self):
        """get size (protected access)"""
        return self._size

    def __str__(self):
        self.update()
        # return super().__str__()  # this brings out the dict character
        return f"<{self._IDENTIFIER_} '{self.name}'>"

    def __repr__(self):
        self.update()
        # return super().__repr__()  # this brings out the dict character
        return f"<{self._IDENTIFIER_[0]}[{self.name}]>"

    def __len__(self):
        self.update()
        assert self._size == sum(
            len(keymap) for keymap in self.values(recursive=True)
        )
        return self._size

    @staticmethod
    def from_file(filename):
        """get the keymap from a file"""
        with open(filename, "rb") as handle:
            ret = pickle.load(handle)
        ret._update()
        return ret

    def to_file(self, filename):
        """write the keymap to a file"""
        with open(filename, "wb") as handle:
            pickle.dump(self, handle)

    @property
    def is_ud(self):
        """read-only access to update flag"""
        return self._is_ud_flag

    def reorder(self, function):
        """reorder the arrangement of keys in the map by some sorting function"""
        self._content = sorted(
            [
                (sort_id, key, keymap)
                for key, keymap in self._content
                if (sort_id := function(key, keymap)) is not None
            ]
        )
        self.flag_ud()

    def flag_ud(self):
        """mark for update"""
        self._is_ud_flag = False
        for parent in self._parents:
            parent.flag_ud()

    def _append(self, key, keymap):
        assert isinstance(key, _Key)
        self._content.append((key, keymap))

    def append(self, key, keymap=None, check=__debug__):
        """append a keymap object at a key"""
        key_obj = self._keygen(key)
        if keymap is None:
            keymap = Entry(str(key))
        if check:
            for tkey, _ in self._content:
                if tkey == key_obj:
                    raise KeyError(f"Key '{key_obj}' already exists")
        self._append(key_obj, keymap)
        keymap.add_parent(self)
        self.flag_ud()

    def add_parent(self, parent):
        """add as a parent if not yet there"""
        if parent not in self._parents:
            self._parents.append(parent)

    def update(self):
        """user-friendly update procedure. Skips update if already up to date,
        asserts up-to-date flag and"""
        ret = True
        if not self.is_ud:
            ret = self._update()
        assert ret
        return self

    def _update(self):
        """the actual update routine"""

        # reset internal stuff
        self._reset()
        offset_pointer = 0

        # go through keymaps in content
        for key, keymap in self._content:
            keymap.update()
            if keymap.size <= 0:
                print(f"skipping keymap {keymap} as it is empty")
                continue

            self._key2reg[key] = keymap
            self._key2pos[key] = offset_pointer
            for offset in range(len(keymap)):
                self._pos2reg.append((keymap, offset))
                offset_pointer += 1
        assert len(self._pos2reg) == offset_pointer
        self._size = offset_pointer
        self._is_ud_flag = True

        return self._is_ud_flag

    def __getitem__(self, key):
        self.update()
        if isinstance(key, Key):
            return self._key2reg[key._keys[0]]
        if not isinstance(key, _Key):
            return self._key2reg[_Key(key)]
        return self._key2reg[key]

    def keys(self, recursive=False, prefix=Key()):
        """generator equivalent to dict's keys function"""
        for key, reg in self._key2reg.items():
            if recursive:
                yield from reg.keys(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(prefix, key)

    def items(self, recursive=False, prefix=Key()):
        """generator equivalent to dict's items function"""
        for key, reg in self._key2reg.items():
            if recursive:
                yield from reg.items(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(key), reg

    def values(self, recursive=False):
        """generator equivalent to dict's values function"""
        for key, reg in self._key2reg.items():
            if recursive:
                yield from reg.values(recursive=True)
            else:
                yield reg


class Region(KeyMap):
    """Region is a keymap which is trivially indexed by integer keys"""

    _IDENTIFIER_ = "Region"
    _ENUM_ = 0

    def __init__(self, size, name=None):
        # autoname
        super().__init__(name=name)
        self._counter = 0
        for count in range(size):
            self.append(Entry(name=f"{self.name}+{count}"))
        self.update()

    def append(self, entry):
        super().append(key=self._counter, keymap=entry)
        self._counter += 1

    def reorder(self, function):
        raise InvalidOperation("Reordering regions is not supported")


class Entry(Region):
    """A Region of size 1"""

    _IDENTIFIER_ = "Entry"
    _ENUM_ = 0

    def __init__(self, name=None):
        super().__init__(0, name=name)
        self._is_ud_flag = True
        self._size = 1

    def keys(self, recursive=False, prefix=Key()):
        yield Key(prefix)

    def items(self, recursive=False, prefix=Key()):
        yield Key(prefix), self

    def values(self, recursive=False):
        yield self

    def _update(self):
        """the actual update routine"""
        self._size = 1
        self._is_ud_flag = True
        return self._is_ud_flag

    def flag_ud(self):
        pass

    def __len__(self):
        return 1

    def _generate_keygen(self, name):
        return _Key


